INSERT INTO lectures (id,learning_objective_id,title,explanation,key_points_json,common_mistakes_json,related_law_json,estimated_minutes,status) VALUES
('lec-rv-admin-procedure-criteria','lo-admin-procedure-criteria','審査基準と処分基準を主語から見分ける','審査基準は申請に対する許認可等の判断基準、処分基準は不利益処分をするか、その内容をどうするかの判断基準です。まず対象となる行政活動を特定し、次に設定義務・具体化・公表の扱いを分けて確認します。','["審査基準は申請に対する処分の判断基準","処分基準は不利益処分の判断基準","設定と公表を別々に判定する","条文の義務と努力義務を一語ずつ確認する"]','["名称だけで制度を決める","審査基準と処分基準の公表ルールを同一視する"]','[{"law":"行政手続法","articles":"5条〜8条・12条〜14条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/405AC0000000088"}]',7,'REVIEWED'),
('lec-rv-admin-procedure-application','lo-admin-procedure-application','申請受付から拒否理由までの行政手続','申請に対する処分では、審査基準、標準処理期間、到達した申請の審査、拒否処分の理由提示を順番で整理します。標準処理期間の設定は努力義務ですが、設定した場合の公表や、拒否理由を示す時点は別の規律です。','["申請が行政庁の事務所へ到達した後の取扱い","標準処理期間は設定と公表を分ける","拒否理由は原則として処分と同時","明白な不適合には理由提示時期の例外がある"]','["努力義務を義務と断定する","理由を後日示せば常に足りると考える"]','[{"law":"行政手続法","articles":"5条〜8条・12条〜14条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/405AC0000000088"}]',7,'REVIEWED'),
('lec-rv-bank-admin-procedure','lo-bank-admin-procedure','行政手続法の全体地図','行政手続法は、申請に対する処分、不利益処分、行政指導、届出、命令等制定手続という場面別に読むと整理できます。問題文の行為をどの章へ置くか決めてから、主体、手続、時期、例外を確認します。','["申請処分と不利益処分を最初に分類する","行政指導には任意性の保障がある","届出は到達時の効果を確認する","命令等制定手続では意見公募を確認する"]','["すべての行政活動に同じ手続が適用されると考える","適用除外を確認しない"]','[{"law":"行政手続法","articles":"5条〜8条・12条〜14条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/405AC0000000088"}]',9,'REVIEWED'),
('lec-rv-admin-appeal-period','lo-admin-appeal-period','審査請求期間の二重の時計','処分についての審査請求は、処分を知った日の翌日から三月という主観的期間と、処分の日の翌日から一年という客観的期間の双方を確認します。正当な理由による例外と、再調査の請求を経た場合などの特則は別に検討します。','["知った日の翌日から三月","処分の日の翌日から一年","二つの期間を両方満たす","正当な理由の例外を最後に確認する"]','["取消訴訟の六箇月と混同する","処分当日を起算日にする"]','[{"law":"行政不服審査法","articles":"18条・25条・44条〜53条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/426AC0000000068"}]',7,'REVIEWED'),
('lec-rv-admin-appeal-suspension','lo-admin-appeal-suspension','審査請求と執行停止','審査請求をしても処分の効力や執行は当然には停止しません。審査庁の類型を確認したうえで、申立てまたは職権による停止、重大な損害を避けるための要件、公共の福祉への重大な影響などを順に判断します。','["執行不停止が原則","申立てと職権の可否は審査庁の類型で確認","損害の重大性と緊急性を検討","停止できない事由も確認する"]','["審査請求だけで自動停止すると考える","裁判所の執行停止と主体を混同する"]','[{"law":"行政不服審査法","articles":"18条・25条・44条〜53条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/426AC0000000068"}]',7,'REVIEWED'),
('lec-rv-bank-admin-appeal','lo-bank-admin-appeal','行政不服審査法の救済フロー','処分または不作為に不服があるとき、対象、審査請求先、期間、審理員手続、行政不服審査会等への諮問、裁決、執行停止の順で全体像を作ります。誰がどの判断をするかを矢印で結ぶのが有効です。','["処分と不作為を区別する","審査庁と審理員の役割を分ける","裁決の種類と拘束力を確認する","教示と不服申立期間を関連付ける"]','["旧制度の異議申立てを現行制度へ持ち込む","審理員と審査庁を同一視する"]','[{"law":"行政不服審査法","articles":"18条・25条・44条〜53条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/426AC0000000068"}]',9,'REVIEWED'),
('lec-rv-admin-litigation-cancel','lo-admin-litigation-cancel','取消訴訟を五つの箱で整理する','取消訴訟は、対象となる処分・裁決、原告適格、被告、出訴期間、判決の効力に分けて整理します。審査請求前置が例外であること、主観的期間と客観的期間、取消判決の第三者効と拘束力を混同しないことが重要です。','["対象","原告適格","被告","出訴期間","判決の効力"]','["審査請求の期間と混同する","処分庁を常に被告とする"]','[{"law":"行政事件訴訟法","articles":"3条・9条・11条・14条・25条・32条〜33条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/337AC0000000139"}]',7,'REVIEWED'),
('lec-rv-admin-litigation-suspension','lo-admin-litigation-suspension','取消訴訟の執行停止を判断する','取消訴訟を提起しても処分の効力等は当然には停止しません。裁判所は申立てにより、重大な損害を避けるため緊急の必要がある場合に停止できますが、本案に理由がないとみえる場合などには認められません。','["訴え提起による自動停止はない","裁判所への申立てが必要","重大な損害と緊急の必要を確認","消極要件を確認する"]','["行政不服審査法の職権停止と混同する","単なる損害があれば足りると考える"]','[{"law":"行政事件訴訟法","articles":"3条・9条・11条・14条・25条・32条〜33条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/337AC0000000139"}]',7,'REVIEWED'),
('lec-rv-bank-admin-litigation','lo-bank-admin-litigation','行政事件訴訟の類型と選択','抗告訴訟には取消訴訟、無効等確認、不作為の違法確認、義務付け、差止めがあります。これに当事者訴訟、民衆訴訟、機関訴訟を加え、求める救済から訴訟類型を逆引きします。','["抗告訴訟の各類型","当事者訴訟との区別","原告適格と訴えの利益","仮の義務付け・仮の差止め"]','["求める救済と訴訟類型が一致しない","無効確認と取消訴訟を同じ期間制限で処理する"]','[{"law":"行政事件訴訟法","articles":"3条・9条・11条・14条・25条・32条〜33条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/337AC0000000139"}]',9,'REVIEWED'),
('lec-rv-state-liability-core','lo-state-liability-core','国家賠償法一条と二条の分岐','一条は公権力の行使に当たる公務員の故意・過失による違法な加害、二条は道路・河川その他の公の営造物の設置または管理の瑕疵を中心に規律します。人の行為か物的施設の安全性かを最初に分けます。','["一条は公務員の職務行為","二条は公の営造物の設置・管理の瑕疵","賠償主体は国または公共団体","求償要件を本体責任と分ける"]','["二条にも特定公務員の過失を要求する","国が無条件に公務員へ求償できると考える"]','[{"law":"国家賠償法","articles":"1条・2条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/322AC0000000125"}]',7,'REVIEWED'),
('lec-rv-bank-state-liability','lo-bank-state-liability','国家賠償法の条文を責任類型で読む','国家賠償法は条文数が少ないため、各条の役割を正確に結び付けます。一条・二条の責任類型、費用負担者、民法の適用、相互保証を並べて覚えると、主体や要件の取り違えを防げます。','["一条責任","二条責任","費用負担者の責任","民法との関係","外国人への相互保証"]','["条文数が少ないため例外確認を省く","賠償主体と費用負担者を混同する"]','[{"law":"国家賠償法","articles":"1条・2条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/322AC0000000125"}]',7,'REVIEWED'),
('lec-rv-bank-local-gov','lo-bank-local-gov','地方自治法の機関と住民統制','地方自治法は、普通地方公共団体の事務、条例・規則、議会と長、執行機関、直接請求、監査請求・住民訴訟という軸で整理します。議決機関と執行機関の権限関係を中心に学びます。','["条例は法律の範囲内で制定する","議会と長の権限を区別する","直接請求の種類と必要署名数を整理する","住民監査請求と住民訴訟を接続する"]','["議会と長の権限を相互に置き換える","住民訴訟を監査請求なしで常に提起できると考える"]','[{"law":"地方自治法","articles":"1条の2・14条・74条以下・89条以下・138条の2以下・242条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/322AC0000000067"}]',10,'REVIEWED'),
('lec-rv-bank-gyoseishoshi','lo-bank-gyoseishoshi','行政書士法の業務・義務・懲戒','行政書士法は、制度目的、行政書士となる資格、官公署提出書類等の作成・提出手続代理、業務上の義務、行政書士会、懲戒を大きな箱にします。業務範囲は他法令による制限を必ず確認します。','["書類作成と提出手続代理","他の法律で制限される業務を除く","守秘義務と品位保持","登録・会・懲戒の主体を確認する"]','["行政書士があらゆる法律事務を扱えると考える","登録機関と懲戒主体を混同する"]','[{"law":"行政書士法","articles":"1条・1条の2・1条の3・10条・12条・14条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/326AC1000000004"}]',8,'REVIEWED'),
('lec-rv-civil-manifestation','lo-civil-manifestation','意思表示の瑕疵を効果で整理する','心裡留保、虚偽表示、錯誤、詐欺・強迫は、成立要件、効果、第三者保護を横並びで比較します。現行民法では錯誤の効果が取消しであること、第三者詐欺では相手方の認識可能性が問題となることを押さえます。','["心裡留保は原則有効","虚偽表示は当事者間で無効","重要な錯誤は取消し","詐欺・強迫と第三者保護"]','["錯誤を当然無効とする","第三者詐欺で相手方の認識を確認しない"]','[{"law":"民法","articles":"1条・93条〜96条・166条・541条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/129AC0000000089"}]',7,'REVIEWED'),
('lec-rv-civil-cancel-void','lo-civil-cancel-void','無効と取消しの法的効果','無効は初めから法律効果が認められないのに対し、取消し得る行為は取り消されるまで効力を持ちます。主張できる者、追認、期間制限、第三者との関係を比較して整理します。','["無効は原則として誰でも主張できる","取消権者は法律で限定される","追認できるかを確認する","取消権の期間制限を確認する"]','["無効と取消しを日常語の強弱だけで判断する","取消し前から当然に無効と扱う"]','[{"law":"民法","articles":"1条・93条〜96条・166条・541条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/129AC0000000089"}]',7,'REVIEWED'),
('lec-rv-civil-limitation','lo-civil-limitation','債権の消滅時効は二つの起算点で覚える','債権は、権利を行使できることを知った時から五年間、または権利を行使できる時から十年間行使しないときに時効で消滅します。完成猶予・更新、援用、利益の放棄を別の論点として整理します。','["主観的起算点から五年","客観的起算点から十年","完成猶予と更新を区別する","時効の援用が必要"]','["常に一律十年と覚える","期間経過だけで裁判所が自動適用すると考える"]','[{"law":"民法","articles":"1条・93条〜96条・166条・541条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/129AC0000000089"}]',7,'REVIEWED'),
('lec-rv-civil-contract-cancel','lo-civil-contract-cancel','催告解除と無催告解除','催告解除は相当期間を定めて履行を催告し、その期間内に履行がないことが基本です。ただし不履行が社会通念上軽微なら解除できません。履行不能や履行拒絶などの無催告解除事由と分けて判断します。','["相当期間を定めた催告","期間内に履行がない","軽微な不履行では解除不可","無催告解除事由を別に確認する"]','["わずかな不履行でも必ず解除できると考える","損害賠償と解除を択一関係にする"]','[{"law":"民法","articles":"1条・93条〜96条・166条・541条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/129AC0000000089"}]',7,'REVIEWED'),
('lec-rv-bank-civil-code','lo-bank-civil-code','民法を五編の地図で読む','民法は総則、物権、債権、親族、相続の五編です。個別条文を覚える前に、法律行為・代理・時効、物権変動、契約・不法行為、身分関係のどこに問題が属するかを決めます。','["総則の規定が各編へ及ぶ関係","物権と債権の区別","契約の成立・履行・不履行","親族・相続の身分法的特徴"]','["条文番号だけを孤立して覚える","特則より先に一般則だけで結論を出す"]','[{"law":"民法","articles":"1条・93条〜96条・166条・541条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/129AC0000000089"}]',10,'REVIEWED'),
('lec-rv-constitution-rights-core','lo-constitution-rights-core','人権条文を保障・制約・救済で読む','基本的人権は、保障される利益、権利主体、制約の根拠、審査の考え方、救済を順に検討します。平等、精神的自由、経済的自由、身体の自由、社会権、参政権・国務請求権を体系化します。','["権利の保障範囲を確定する","権利主体を確認する","制約の目的と手段を検討する","条文と主要判例の役割を分ける"]','["公共の福祉だけで直ちに合憲とする","条文の文言と判例基準を混同する"]','[{"law":"日本国憲法","articles":"1条・11条〜14条・21条・31条・41条以下・98条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/321CONSTITUTION"}]',7,'REVIEWED'),
('lec-rv-bank-constitution','lo-bank-constitution','日本国憲法の統治と人権の全体像','憲法は国民主権、基本的人権の尊重、平和主義を基本原理とし、国会、内閣、司法、財政、地方自治、改正、最高法規を定めます。人権問題と統治問題を分け、最後に相互関係を確認します。','["三大原理","国会・内閣・裁判所の権限","違憲審査制","地方自治","最高法規と改正手続"]','["国会を唯一の立法機関だから無制限と考える","条約と法律の関係を憲法との関係と混同する"]','[{"law":"日本国憲法","articles":"1条・11条〜14条・21条・31条・41条以下・98条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/321CONSTITUTION"}]',10,'REVIEWED'),
('lec-rv-basic-personal-info','lo-basic-personal-info','個人情報の取得から提供まで','個人情報取扱事業者の義務は、利用目的の特定、適正取得、取得時の通知・公表、安全管理、第三者提供、開示等の請求という情報の流れで整理します。個人情報、個人データ、保有個人データを区別します。','["利用目的をできる限り特定","不正な手段による取得は禁止","要配慮個人情報の取得ルール","個人データの第三者提供","本人による開示等請求"]','["個人情報と個人データを同義にする","同意があればすべての取扱いが許されると考える"]','[{"law":"個人情報の保護に関する法律","articles":"1条・2条・17条・20条・21条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/415AC0000000057"}]',7,'REVIEWED'),
('lec-rv-bank-appi','lo-bank-appi','個人情報保護法の用語階層','個人情報保護法は定義の区別が結論を左右します。個人情報、個人識別符号、要配慮個人情報、個人データ、保有個人データ、匿名加工情報、仮名加工情報の関係を先に整理します。','["定義ごとの包含関係","利用目的による制限","安全管理措置","第三者提供と確認・記録","漏えい等報告"]','["用語をすべて個人情報として一括処理する","例外を確認せず同意の有無だけで決める"]','[{"law":"個人情報の保護に関する法律","articles":"1条・2条・17条・20条・21条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/415AC0000000057"}]',9,'REVIEWED'),
('lec-rv-bank-cybersecurity','lo-bank-cybersecurity','サイバーセキュリティ基本法の役割分担','基本理念、国の責務、地方公共団体・重要社会基盤事業者・サイバー関連事業者・教育研究機関・国民の努力、戦略と推進体制を整理します。罰則中心の法律ではなく政策基本法として読みます。','["サイバーセキュリティの定義","基本理念","各主体の責務・努力","サイバーセキュリティ戦略","推進体制"]','["すべてを法的義務として覚える","個別の不正アクセス規制法と混同する"]','[{"law":"サイバーセキュリティ基本法","articles":"1条〜6条・10条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/426AC1000000104"}]',7,'REVIEWED'),
('lec-rv-bank-electronic-signature','lo-bank-electronic-signature','電子署名の推定と認証業務','電子署名法では電子署名の定義、本人による電子署名が行われた電磁的記録の真正な成立の推定、特定認証業務の認定制度を分けて整理します。すべての電子的操作が同じ効果を持つわけではありません。','["電子署名の定義","真正な成立の推定要件","特定認証業務","認定制度と主務大臣"]','["電子メール末尾の氏名を常に電子署名とする","認定がなければ電子署名の効力がないと考える"]','[{"law":"電子署名及び認証業務に関する法律","articles":"2条・3条・4条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/412AC0000000102"}]',7,'REVIEWED'),
('lec-rv-bank-public-records','lo-bank-public-records','公文書のライフサイクル管理','行政文書の作成、整理、保存、行政文書ファイル管理簿、移管または廃棄、特定歴史公文書等の保存・利用までを一連の流れで整理します。意思決定過程を合理的に跡付けられる文書作成が出発点です。','["文書作成義務","整理・保存","管理簿への記載","移管と廃棄","国立公文書館等での利用"]','["情報公開法の開示請求手続と混同する","保存期間満了で自由に廃棄できると考える"]','[{"law":"公文書等の管理に関する法律","articles":"1条・4条〜8条・14条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/421AC0000000066"}]',7,'REVIEWED'),
('lec-rv-bank-information-disclosure','lo-bank-information-disclosure','情報公開法の開示・不開示判断','何人も行政文書の開示を請求できます。行政機関の長は、不開示情報が記録されている場合を除き開示するのが原則です。個人情報、法人情報、国の安全、公共の安全、審議検討、事務事業情報を類型別に判断します。','["請求権者は何人も","行政文書該当性","不開示情報の各類型","部分開示","存否応答拒否と不服救済"]','["個人情報はすべて一律不開示とする","保有していない文書を作成して開示すると考える"]','[{"law":"行政機関の保有する情報の公開に関する法律","articles":"1条・3条・5条・9条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/411AC0000000042"}]',7,'REVIEWED'),
('lec-rv-bank-my-number','lo-bank-my-number','番号利用法の利用・提供制限','番号利用法は、個人番号の利用範囲、提供の求めと提供の制限、特定個人情報の保護、情報提供ネットワークシステム、個人番号カードを整理します。便利さだけでなく目的外利用を抑える構造が重要です。','["個人番号を利用できる事務","提供制限","特定個人情報","情報提供ネットワーク","個人番号カード"]','["本人同意があれば自由に利用・提供できると考える","個人番号と法人番号を同じ制限で扱う"]','[{"law":"行政手続における特定の個人を識別するための番号の利用等に関する法律","articles":"1条〜3条・9条・19条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/425AC0000000027"}]',7,'REVIEWED'),
('lec-rv-bank-company-act','lo-bank-company-act','会社法を機関・株式・計算で整理する','会社法は会社の種類、設立、株式、機関、計算、組織再編を大きな柱にします。株式会社では公開会社か、取締役会設置会社か、大会社かなどの属性が適用条文を分けます。','["会社類型","設立手続","株式と株主","機関設計","計算・組織再編"]','["すべての株式会社に同じ機関が必要と考える","公開会社と上場会社を同義にする"]','[{"law":"会社法","articles":"1条・295条・296条・362条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/417AC0000000086"}]',10,'REVIEWED'),
('lec-rv-company-shareholders-meeting','lo-company-shareholders-meeting','株主総会の権限と招集','非取締役会設置会社の株主総会は会社に関する一切の事項を決議できますが、取締役会設置会社では法律または定款に定める事項に限られます。定時総会、臨時総会、招集権者、招集通知を順に整理します。','["取締役会設置の有無で権限が変わる","定時総会は毎事業年度終了後一定時期","必要があれば臨時総会を招集できる","原則として取締役が招集する"]','["取締役会設置会社でも一切の事項を決議できるとする","定時総会を暦年一回と固定する"]','[{"law":"会社法","articles":"1条・295条・296条・362条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/417AC0000000086"}]',7,'REVIEWED'),
('lec-rv-bank-commercial-code','lo-bank-commercial-code','商法の総則と商行為','商法は商人、商行為、商業登記、商号、商業帳簿、商業使用人、代理商、運送・海商などを規律します。会社法との適用関係を確認し、民法に対する商事特則として働く場面を整理します。','["商人と商行為","商号・商業登記","商業使用人","商事売買などの特則","運送・海商"]','["会社に関する規定をすべて商法だけで探す","民法の一般則との適用順序を確認しない"]','[{"law":"商法","articles":"1条〜7条・501条以下","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/132AC0000000048"}]',9,'REVIEWED'),
('lec-rv-bank-general-rules','lo-bank-general-rules','準拠法を法律関係ごとに決める','法の適用に関する通則法は、法律の施行期日等の通則に加え、国際的な私法関係の準拠法を定めます。法律行為、物権、債権、不法行為、親族、相続など法律関係ごとに連結点を確認します。','["法律関係を先に性質決定する","当事者自治と客観的連結","物権の所在地法","不法行為の準拠法","公序による外国法適用排除"]','["国籍だけで全ての準拠法を決める","準拠法選択と国際裁判管轄を混同する"]','[{"law":"法の適用に関する通則法","articles":"1条〜4条・7条以下・42条〜43条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/418AC0000000078"}]',9,'REVIEWED'),
('lec-rv-jurisprudence-supreme-law','lo-jurisprudence-supreme-law','最高法規性と法規範の優劣','憲法は国の最高法規であり、これに反する法律、命令、詔勅その他の国務に関する行為は効力を有しません。また、日本国が締結した条約と確立された国際法規を誠実に遵守することを定めます。','["憲法が最高法規","違憲な下位規範は効力を有しない","条約と確立された国際法規の誠実遵守","違憲審査権との関係"]','["命令だけが違憲審査の対象になると考える","条約を憲法より上位と条文だけから即断する"]','[{"law":"日本国憲法","articles":"1条・11条〜14条・21条・31条・41条以下・98条","referenceDate":"2026-04-01","url":"https://laws.e-gov.go.jp/law/321CONSTITUTION"}]',7,'REVIEWED');
INSERT INTO questions (id,learning_objective_id,exam_year,question_type,stem,normalized_text,fingerprint,correct_explanation,reveal_hint,judgment_point,difficulty,status,is_ai_training,importance,license_status,legal_rule,published_at) VALUES
('q-write-admin-reason','lo-admin-procedure-application',2026,'WRITING','申請に対する許認可等を拒否する処分をする場合、理由提示の原則を40字程度で記述してください。','申請に対する許認可等を拒否する処分をする場合、理由提示の原則を40字程度で記述してください。','write26-800645d931924eceb204f5bb','解答では、対象・時期・内容を落とさず、40字前後で法的効果まで示します。模範解答は「行政庁は、原則として拒否処分と同時に、その理由を申請者に示さなければならない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','行政手続法8条','2026-08-19 00:00:00'),
('q-write-appeal-period','lo-admin-appeal-period',2026,'WRITING','処分についての審査請求期間の原則を、二つの起算点を含め40字程度で記述してください。','処分についての審査請求期間の原則を、二つの起算点を含め40字程度で記述してください。','write26-b05b65d8a8b40029ff218a07','解答では、主観的期間・客観的期間を落とさず、40字前後で法的効果まで示します。模範解答は「処分を知った日の翌日から三月、処分の日の翌日から一年以内に審査請求する。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','行政不服審査法18条','2026-08-19 00:00:00'),
('q-write-litigation-period','lo-admin-litigation-cancel',2026,'WRITING','取消訴訟の出訴期間の原則を、二つの期間を含め40字程度で記述してください。','取消訴訟の出訴期間の原則を、二つの期間を含め40字程度で記述してください。','write26-e2641a8f9ea692edad8b8fe2','解答では、主観的期間・客観的期間を落とさず、40字前後で法的効果まで示します。模範解答は「処分等を知った日から六箇月、処分等の日から一年を経過すると提起できない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','行政事件訴訟法14条','2026-08-19 00:00:00'),
('q-write-state-one','lo-state-liability-core',2026,'WRITING','国家賠償法1条1項の賠償責任の基本要件を40字程度で記述してください。','国家賠償法1条1項の賠償責任の基本要件を40字程度で記述してください。','write26-d84a0dd881a917a93d40c80b','解答では、行為者・帰責事由・違法性・責任主体を落とさず、40字前後で法的効果まで示します。模範解答は「公務員が職務上、故意又は過失により違法に損害を加えたとき、国等が賠償する。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','国家賠償法1条','2026-08-19 00:00:00'),
('q-write-civil-error','lo-civil-manifestation',2026,'WRITING','民法95条による錯誤の効果と重要性の要件を40字程度で記述してください。','民法95条による錯誤の効果と重要性の要件を40字程度で記述してください。','write26-061dadf22aa79cf5a8b843bc','解答では、判断基準・重要性・効果を落とさず、40字前後で法的効果まで示します。模範解答は「法律行為の目的と取引通念に照らして重要な錯誤による意思表示は、取り消すことができる。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','民法95条','2026-08-19 00:00:00'),
('q-write-civil-cancel','lo-civil-contract-cancel',2026,'WRITING','催告解除の原則と軽微な不履行の例外を40字程度で記述してください。','催告解除の原則と軽微な不履行の例外を40字程度で記述してください。','write26-3d136181e54d6b912fe5aedd','解答では、催告・不履行・効果・例外を落とさず、40字前後で法的効果まで示します。模範解答は「催告期間内に履行がなければ解除できるが、不履行が軽微なときは解除できない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','民法541条','2026-08-19 00:00:00'),
('q-write-constitution-process','lo-constitution-rights-core',2026,'WRITING','日本国憲法31条が保障する内容を40字程度で記述してください。','日本国憲法31条が保障する内容を40字程度で記述してください。','write26-5555e236f4ae908682565556','解答では、手続の根拠・保護対象を落とさず、40字前後で法的効果まで示します。模範解答は「法律の定める手続によらなければ、生命・自由を奪われ又は刑罰を科されない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','日本国憲法31条','2026-08-19 00:00:00'),
('q-write-appi-purpose','lo-basic-personal-info',2026,'WRITING','個人情報保護法上の利用目的の特定と変更限界を40字程度で記述してください。','個人情報保護法上の利用目的の特定と変更限界を40字程度で記述してください。','write26-e4ae2f22b6eb67a230360c98','解答では、特定義務・変更限界を落とさず、40字前後で法的効果まで示します。模範解答は「利用目的をできる限り特定し、変更は合理的関連性の範囲を超えてはならない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','個人情報の保護に関する法律17条','2026-08-19 00:00:00'),
('q-write-company-authority','lo-company-shareholders-meeting',2026,'WRITING','取締役会設置会社の株主総会の権限を40字程度で記述してください。','取締役会設置会社の株主総会の権限を40字程度で記述してください。','write26-01fb25470ac2e33cc528e3bc','解答では、対象会社・権限の範囲を落とさず、40字前後で法的効果まで示します。模範解答は「株主総会は、会社法又は定款に定める事項に限り、決議することができる。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','会社法295条','2026-08-19 00:00:00'),
('q-write-supreme-law','lo-jurisprudence-supreme-law',2026,'WRITING','日本国憲法98条1項の最高法規性の効果を40字程度で記述してください。','日本国憲法98条1項の最高法規性の効果を40字程度で記述してください。','write26-93bd5e4c6e0351e54b742055','解答では、抵触・下位規範・効果を落とさず、40字前後で法的効果まで示します。模範解答は「憲法に反する法律、命令等の国務に関する行為は、その効力を有しない。」です。','主体・要件・時期・効果のうち、問われている要素を先に箇条書きします。','必要要素を40字前後へ圧縮する','EXAM','REVIEWED',0,1.4,'ORIGINAL','日本国憲法98条1項','2026-08-19 00:00:00');
INSERT INTO writing_rubrics (id,question_id,model_answer,required_elements_json,keywords_json,accepted_phrases_json,subject_role,counterparty,legal_relationship,requirements,effect,legal_basis,rubric_json) VALUES
('rubric-q-write-admin-reason','q-write-admin-reason','行政庁は、原則として拒否処分と同時に、その理由を申請者に示さなければならない。','["対象","時期","内容"]','["拒否処分","同時","理由提示"]','["拒否処分","拒否","同時","理由","示さ","提示"]','対象',NULL,NULL,'対象・時期・内容','必要要素を満たす40字前後の記述','行政手続法8条','{"groups":[["拒否処分","拒否"],["同時"],["理由"],["示さ","提示"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-appeal-period','q-write-appeal-period','処分を知った日の翌日から三月、処分の日の翌日から一年以内に審査請求する。','["主観的期間","客観的期間"]','["三月","一年","翌日"]','["知った日","知り","翌日","三月","3月","処分の日","一年","1年"]','主観的期間',NULL,NULL,'主観的期間・客観的期間','必要要素を満たす40字前後の記述','行政不服審査法18条','{"groups":[["知った日","知り"],["翌日"],["三月","3月"],["処分の日"],["一年","1年"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-litigation-period','q-write-litigation-period','処分等を知った日から六箇月、処分等の日から一年を経過すると提起できない。','["主観的期間","客観的期間"]','["六箇月","一年","取消訴訟"]','["知った日","六箇月","6か月","6箇月","処分の日","裁決の日","一年","1年"]','主観的期間',NULL,NULL,'主観的期間・客観的期間','必要要素を満たす40字前後の記述','行政事件訴訟法14条','{"groups":[["知った日"],["六箇月","6か月","6箇月"],["処分の日","裁決の日"],["一年","1年"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-state-one','q-write-state-one','公務員が職務上、故意又は過失により違法に損害を加えたとき、国等が賠償する。','["行為者","帰責事由","違法性","責任主体"]','["公務員","故意","過失","違法","国"]','["公務員","職務","公権力","故意","過失","違法","国","公共団体"]','行為者',NULL,NULL,'行為者・帰責事由・違法性・責任主体','必要要素を満たす40字前後の記述','国家賠償法1条','{"groups":[["公務員"],["職務","公権力"],["故意","過失"],["違法"],["国","公共団体"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-civil-error','q-write-civil-error','法律行為の目的と取引通念に照らして重要な錯誤による意思表示は、取り消すことができる。','["判断基準","重要性","効果"]','["取引通念","重要","錯誤","取消し"]','["目的","取引通念","重要","錯誤","取消"]','判断基準',NULL,NULL,'判断基準・重要性・効果','必要要素を満たす40字前後の記述','民法95条','{"groups":[["目的"],["取引通念"],["重要"],["錯誤"],["取消"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-civil-cancel','q-write-civil-cancel','催告期間内に履行がなければ解除できるが、不履行が軽微なときは解除できない。','["催告","不履行","効果","例外"]','["催告","履行","解除","軽微"]','["催告","期間","履行","解除","軽微"]','催告',NULL,NULL,'催告・不履行・効果・例外','必要要素を満たす40字前後の記述','民法541条','{"groups":[["催告"],["期間"],["履行"],["解除"],["軽微"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-constitution-process','q-write-constitution-process','法律の定める手続によらなければ、生命・自由を奪われ又は刑罰を科されない。','["手続の根拠","保護対象"]','["法律","手続","生命","自由","刑罰"]','["法律","手続","生命","自由","刑罰"]','手続の根拠',NULL,NULL,'手続の根拠・保護対象','必要要素を満たす40字前後の記述','日本国憲法31条','{"groups":[["法律"],["手続"],["生命","自由"],["刑罰"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-appi-purpose','q-write-appi-purpose','利用目的をできる限り特定し、変更は合理的関連性の範囲を超えてはならない。','["特定義務","変更限界"]','["利用目的","特定","合理的関連性"]','["利用目的","特定","変更","合理的","関連性","超えてはならない","超えない"]','特定義務',NULL,NULL,'特定義務・変更限界','必要要素を満たす40字前後の記述','個人情報の保護に関する法律17条','{"groups":[["利用目的"],["特定"],["変更"],["合理的","関連性"],["超えてはならない","超えない"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-company-authority','q-write-company-authority','株主総会は、会社法又は定款に定める事項に限り、決議することができる。','["対象会社","権限の範囲"]','["株主総会","会社法","定款","決議"]','["株主総会","会社法","法律","定款","限り","決議"]','対象会社',NULL,NULL,'対象会社・権限の範囲','必要要素を満たす40字前後の記述','会社法295条','{"groups":[["株主総会"],["会社法","法律"],["定款"],["限り"],["決議"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}'),
('rubric-q-write-supreme-law','q-write-supreme-law','憲法に反する法律、命令等の国務に関する行為は、その効力を有しない。','["抵触","下位規範","効果"]','["憲法","法律","命令","効力"]','["憲法","反する","違反","法律","命令","効力","有しない","無効"]','抵触',NULL,NULL,'抵触・下位規範・効果','必要要素を満たす40字前後の記述','日本国憲法98条1項','{"groups":[["憲法"],["反する","違反"],["法律","命令"],["効力"],["有しない","無効"]],"minimumRatio":0.7,"minLength":20,"maxLength":60}');
